// Perkalian silang. Hasilnya memberi tahu titik (px, py) berada di sebelah
// mana dari garis yang melalui (ax, ay) menuju (bx, by).
// Positif = sisi kiri, negatif = sisi kanan, nol = tepat di garis.
long long silang(long long ax, long long ay, long long bx, long long by,
                 long long px, long long py) {
    return (bx - ax) * (py - ay) - (by - ay) * (px - ax);
